```javascript
const axios = require("axios");

async function getData(input) {
  try {
    const response = await axios.get(
      "https://api.microlink.io/",
      {
        params: {
          url: input,
          iframe: "true",
          audio: "true",
          video: "true"
        }
      }
    );

    return response.data;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

getData("https://kyzorohan.web.id")
  .then(result => m.reply(JSON.stringify(result, null, 2)))
  .catch(error => m.reply(error.message));
```
